def _openai_chat(messages, system_prompt=None, max_tokens=1024, temperature=0.7):
    """Merkezi LLM sohbet çağrısı (OpenAI Chat Completions).

    `messages` Anthropic ile uyumlu [{"role","content"}] listesidir; system_prompt
    varsa başa bir system mesajı olarak eklenir. Hata durumunda kullanıcı-dostu bir
    RuntimeError fırlatır; çağıranlar bunu kendi try/except fallback'leriyle yakalar.
    """
    full_messages = []
    if system_prompt:
        full_messages.append({"role": "system", "content": system_prompt})
    full_messages.extend(messages)
    try:
        resp = openai_client.chat.completions.create(
            model=OPENAI_MODEL,
            messages=full_messages,
            max_tokens=max_tokens,
            temperature=temperature,
        )
        # `choices` içerik filtresinde boş, `message.content` ise refuse/length
        # durumlarında None olabilir. Çağıranların çoğu dönüşe doğrudan .strip()
        # uyguluyor; ham IndexError/None'ı buraya hapsedip her zaman str döndür.
        if not resp.choices:
            logger.warning("OpenAI yanıtı boş choices döndürdü (içerik filtresi olası)")
            return ""
        choice = resp.choices[0]
        if getattr(choice, "finish_reason", None) == "length":
            # Yanıt max_tokens sınırında kesildi: çıktı eksik/bozuk olabilir.
            # Sessizce yutulmasın — çağıranların parse hataları bu uyarıyla
            # ilişkilendirilebilsin (docs/menu-extraction-truncation-risk.md).
            logger.warning("OpenAI yanıtı max_tokens=%s sınırında kesildi (finish_reason=length)", max_tokens)
        return choice.message.content or ""
    except RateLimitError:
        raise RuntimeError("AI servisi şu an yoğun (rate limit). Lütfen biraz sonra tekrar deneyin.")
    except (APITimeoutError, APIConnectionError):
        raise RuntimeError("AI servisine ulaşılamadı (zaman aşımı). Lütfen tekrar deneyin.")
    except APIError as e:
        # Ham sağlayıcı hatası kullanıcıya sızmasın (iç ayrıntı/anahtar metası
        # içerebilir); detayı logla, kullanıcıya jenerik mesaj dön.
        logger.warning("OpenAI APIError: %s", e)
        raise RuntimeError("AI servisi hatası. Lütfen tekrar deneyin.")


def _claude_chat(messages, system_prompt=None, max_tokens=1024, temperature=0.7):
    """Ağır görev LLM çağrısı (Claude Sonnet 4.5 — Amazon Bedrock, Messages API).

    `_openai_chat` ile AYNI imzayı taşır; OpenAI-stili argümanları Anthropic'e çevirir:
      • system_prompt ve messages içindeki her {"role":"system"} üst düzey `system=`
        paramına taşınır (Anthropic system rolünü messages içinde kabul etmez).
      • max_tokens, Anthropic'in zorunlu kıldığı sınır için BEDROCK_MAX_TOKENS'a clamp'lenir.
      • Yanıt, ilk text content bloğunun metnidir.
    Hata durumunda `_openai_chat` ile birebir aynı Türkçe RuntimeError'ları fırlatır;
    çağıran (_heavy_chat) bunları yakalayıp OpenAI'ya düşer.
    """
    sys_parts = [system_prompt] if system_prompt else []
    convo = []
    for m in messages:
        if m.get("role") == "system":
            sys_parts.append(m.get("content", ""))
        else:
            convo.append(m)
    system = "\n\n".join(p for p in sys_parts if p)
    capped = min(max_tokens, BEDROCK_MAX_TOKENS)
    try:
        kwargs = dict(model=BEDROCK_MODEL, max_tokens=capped,
                      messages=convo, temperature=temperature)
        if system:
            kwargs["system"] = system
        resp = bedrock_client.messages.create(**kwargs)
        if getattr(resp, "stop_reason", None) == "max_tokens":
            logger.warning("Claude yanıtı max_tokens=%s sınırında kesildi (stop_reason=max_tokens)", capped)
        for block in resp.content:
            if getattr(block, "type", None) == "text":
                return block.text
        return ""
    except anthropic.RateLimitError:
        raise RuntimeError("AI servisi şu an yoğun (rate limit). Lütfen biraz sonra tekrar deneyin.")
    except (anthropic.APITimeoutError, anthropic.APIConnectionError):
        raise RuntimeError("AI servisine ulaşılamadı (zaman aşımı). Lütfen tekrar deneyin.")
    except anthropic.APIError as e:  # APIStatusError bunun alt sınıfıdır — tek except yeter
        logger.warning("Claude/Bedrock APIError: %s", e)
        raise RuntimeError("AI servisi hatası. Lütfen tekrar deneyin.")


def _bedrock_validate_image(image_bytes, media_type, prompt, max_tokens=400, temperature=0.0):
    """Bedrock (Claude Sonnet) çok-kipli doğrulama: bir görsel + metin promptu gönderir,
    modelin ham metin yanıtını (genelde katı JSON) string olarak döndürür.

    Anthropic Messages API GÖRSEL BLOĞU kullanır — OpenAI'ın `image_url`'ü DEĞİL:
        {"type":"image","source":{"type":"base64","media_type":..., "data": <b64>}}
    Yalnızca BEDROCK_ENABLED ve anthropic paketi mevcutken çağrılmalı (çağıran kontrol
    eder). Hata durumunda _claude_chat ile aynı Türkçe RuntimeError'ları fırlatır;
    çağıranlar fail-open/fallback için yakalar."""
    import base64
    if media_type not in ("image/jpeg", "image/png", "image/webp", "image/gif"):
        media_type = "image/jpeg"
    b64 = base64.b64encode(image_bytes).decode("utf-8")
    content = [
        {"type": "text", "text": prompt},
        {"type": "image", "source": {"type": "base64", "media_type": media_type, "data": b64}},
    ]
    try:
        resp = bedrock_client.messages.create(
            model=BEDROCK_MODEL,
            max_tokens=min(max_tokens, BEDROCK_MAX_TOKENS),
            messages=[{"role": "user", "content": content}],
            temperature=temperature,
        )
        for block in resp.content:
            if getattr(block, "type", None) == "text":
                return block.text
        return ""
    except anthropic.RateLimitError:
        raise RuntimeError("AI servisi şu an yoğun (rate limit). Lütfen biraz sonra tekrar deneyin.")
    except (anthropic.APITimeoutError, anthropic.APIConnectionError):
        raise RuntimeError("AI servisine ulaşılamadı (zaman aşımı). Lütfen tekrar deneyin.")
    except anthropic.APIError as e:
        logger.warning("Bedrock görsel doğrulama APIError: %s", e)
        raise RuntimeError("AI servisi hatası. Lütfen tekrar deneyin.")


def _heavy_chat(messages, system_prompt=None, max_tokens=1024, temperature=0.7):
    """Ağır görev yönlendiricisi: Bedrock açıksa Claude Sonnet'e gider, aksi halde veya
    herhangi bir hatada OpenAI'ya şeffafça düşer. İmza `_openai_chat` ile aynıdır, böylece
    çağrı noktaları yalnızca `_openai_chat(` → `_heavy_chat(` rename'iyle taşınır.
    Hangi sağlayıcının cevap verdiğini `[AI]` etiketli INFO satırıyla loglar (gözlemlenebilirlik)."""
    if BEDROCK_ENABLED and anthropic is not None:
        try:
            reply = _claude_chat(messages, system_prompt=system_prompt,
                                 max_tokens=max_tokens, temperature=temperature)
            logger.info("[AI] sağlayıcı: Bedrock (Claude Sonnet)")
            return reply
        except Exception as e:  # RuntimeError dahil her şey → OpenAI'ya düş (istek bozulmasın)
            logger.warning("Bedrock/Claude çağrısı başarısız, OpenAI'ya düşülüyor: %s: %s",
                           type(e).__name__, e)
    logger.info("[AI] sağlayıcı: OpenAI (%s)", OPENAI_MODEL)
    return _openai_chat(messages, system_prompt=system_prompt,
                        max_tokens=max_tokens, temperature=temperature)
